/**
 * Animated previews of the `xfade` transitions, generated by
 * `scripts/generate-transition-previews.mjs` into `assets/transition-previews`.
 */

import { XFADE_TRANSITIONS } from '@/lib/video-program/transition-catalog'

const previewModules = import.meta.glob('../../../../../assets/transition-previews/*.webp', { eager: true, import: 'default', query: '?url' })

const previewUrls = new Map(Object.entries(previewModules).map(([path, url]) => [path.slice(path.lastIndexOf('/') + 1, -'.webp'.length), url]))

/**
 * Returns the URL of a transition's animated preview.
 * @param {string} type `xfade` transition name.
 * @returns {string} Preview URL.
 */
export function transitionPreviewUrl(type) {
  const url = previewUrls.get(type)
  if (url === undefined) throw new Error(`Transition ${type} has no preview; run scripts/generate-transition-previews.mjs`)
  return url
}

/** Transitions whose preview asset is missing (the catalogue and the assets must match). */
export function missingTransitionPreviews() {
  return XFADE_TRANSITIONS.filter((type) => !previewUrls.has(type))
}
